contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry implementing the property-based test
    function run(uint256 sendValue) public payable {
        // ensure this contract has enough ETH to forward if needed
        require(address(this).balance >= sendValue);

        // read pre-state visible values
        uint256 before_balance = c.balanceOf(address(this));
        bool before_blacklisted = c.blacklist(address(this));
        bool distributionFinishedBefore = c.distributionFinished();
        uint256 totalRemainingBefore = c.totalRemaining();

        // attempt to call getTokens forwarding ETH; capture whether it reverted
        bool reverted;
        try c.getTokens{value: sendValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state visible values
        uint256 after_balance = c.balanceOf(address(this));
        bool after_blacklisted = c.blacklist(address(this));
        bool distributionFinishedAfter = c.distributionFinished();
        uint256 totalRemainingAfter = c.totalRemaining();

        // General rule to assert:
        // - If the call reverted, then no visible state changed (balances and blacklist and totalRemaining unchanged).
        // - If the call did not revert, then our balance did not decrease, and either we received tokens (balance increased by some amount <= totalRemainingBefore)
        //   and we became blacklisted, or nothing was given but blacklist may remain as before. Also totalRemaining decreases by the amount given and distributionFinished can only flip from false to true.
        // Expressed compactly as one assert combining these facts.

        assert(
            // If reverted: nothing visible changed
            (reverted && after_balance == before_balance && after_blacklisted == before_blacklisted && totalRemainingAfter == totalRemainingBefore && distributionFinishedAfter == distributionFinishedBefore)
            ||
            // If not reverted: visible invariants hold
            (!reverted
                && after_balance >= before_balance
                // the increase equals the decrease in totalRemaining
                && (after_balance - before_balance == (totalRemainingBefore - totalRemainingAfter))
                // distributed amount cannot exceed previous remaining
                && (totalRemainingBefore >= totalRemainingAfter)
                // if we gained tokens (>0) then we must be blacklisted after the call
                && ((after_balance - before_balance == 0) || after_blacklisted == true)
                // distributionFinished can only go from false to true, not revert to false
                && ( !(distributionFinishedBefore == true && distributionFinishedAfter == false) )
            )
        );
    }

    // receive so this contract can hold ETH to forward
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address to, uint256 amount) public payable {
        require(to != address(0) || to == address(0)); // no precondition on inputs

        // Ensure this contract has at least 'amount' tokens by using the distribution mechanism if possible.
        // Try to call getTokens to obtain tokens for this contract if distribution not finished and not blacklisted.
        bool gotDistr = false;
        // call getTokens via try/catch to avoid bubbling revert
        try c.getTokens{value: 0}() {
            gotDistr = true;
        } catch {
            gotDistr = false;
        }

        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);

        // attempt transfer and record whether it reverted
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 toBalAfter = c.balanceOf(to);

        // The asserted invariant:
        // If transfer succeeded then sender balance decreased by amount and recipient increased by amount.
        // If transfer reverted then either to==address(0) or amount > balBefore (insufficient balance).
        assert((!reverted && balBefore >= amount && balAfter + amount == balBefore && toBalAfter == toBalBefore + amount && to != address(0))
               || (reverted && (to == address(0) || amount > balBefore)));
    }

    // allow receiving ether if needed by c.getTokens and withdraws
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address to, uint256 amount) public payable {
        // restrict inputs so arithmetic in the assertion is safe
        require(to != address(0) && amount <= type(uint256).max);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 toBalAfter = c.balanceOf(to);

        // Single simple assertion: either transfer succeeded and balances moved exactly,
        // or it reverted and that must be because to==address(0) or insufficient balance.
        assert((!reverted && balBefore >= amount && balAfter + amount == balBefore && toBalAfter == toBalBefore + amount)
               || (reverted && (to == address(0) || amount > balBefore)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address spender, uint256 value) public payable {
        require(spender != address(0));

        // observe allowance before
        uint256 before = c.allowance(address(this), spender);

        bool success;
        try c.approve(spender, value) returns (bool r) {
            success = r;
        } catch {
            success = false;
        }

        uint256 after = c.allowance(address(this), spender);

        // General rule: if approve returned true then allowance was set to value; if false then allowance unchanged
        assert((success && after == value) || (!success && after == before));
    }

    receive() external payable {}
}
